import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Troubleshooting","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/distant-horizons-support-pumpkin/docs/troubleshooting.md"},"headers":[],"relativePath":"packages/distant-horizons-support-pumpkin/docs/troubleshooting.md","filePath":"packages/distant-horizons-support-pumpkin/docs/troubleshooting.md","lastUpdated":1792252144000}`),a={name:`packages/distant-horizons-support-pumpkin/docs/troubleshooting.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><h2 id="the-client-disconnects-or-never-opens-a-session" tabindex="-1">The client disconnects or never opens a session <a class="header-anchor" href="#the-client-disconnects-or-never-opens-a-session" aria-label="Permalink to “The client disconnects or never opens a session”">​</a></h2><p>Check the plugin README for the supported Distant Horizons release and make sure the client is running it. If the protocol versions differ, the plugin closes the session. Only Java Edition players can open Distant Horizons sessions.</p><h2 id="requests-stay-pending-because-terrain-is-unavailable" tabindex="-1">Requests stay pending because terrain is unavailable <a class="header-anchor" href="#requests-stay-pending-because-terrain-is-unavailable" aria-label="Permalink to “Requests stay pending because terrain is unavailable”">​</a></h2><p>The plugin can read only chunks Pumpkin has loaded; it cannot load or generate them. If the requested area isn&#39;t loaded and has no cached capture, the request stays pending while the plugin checks again with increasing delays. Bring the area within range of a player or use a server chunk-loading tool. The client can cancel a request it no longer needs, and each pending request uses space in the configured queue. See the plugin README for the section size and capture requirements.</p><h2 id="a-client-sees-old-terrain" tabindex="-1">A client sees old terrain <a class="header-anchor" href="#a-client-sees-old-terrain" aria-label="Permalink to “A client sees old terrain”">​</a></h2><p>The plugin keeps serving a cached capture until it reaches its configured refresh age. It rebuilds an expired capture in the background when the server has the terrain loaded; otherwise, the older capture remains available. Block placement and breaking invalidate affected captures, while other world changes are picked up on a later refresh. If you replace world data or change a dimension&#39;s height, stop the server, remove this plugin&#39;s cache folder, and restart the server. The plugin README lists commands for clearing either cache tier or both.</p><h2 id="requests-stay-queued-or-progress-is-slow" tabindex="-1">Requests stay queued or progress is slow <a class="header-anchor" href="#requests-stay-queued-or-progress-is-slow" aria-label="Permalink to “Requests stay queued or progress is slow”">​</a></h2><p>Run <code>/dhs status</code> to see pending requests, queued responses and retained response bytes, DH packet bytes sent, capture progress, completed and rejected requests, and the last rejection reason. Requests for unavailable terrain retry with increasing delays. If the last rejection is <code>LOD request limit reached</code>, the bounded request queue is full. Cached sections can still be delivered while a forced capture pauses ordinary sampling.</p><p>The client&#39;s ETA includes time spent waiting since submission, so it doesn&#39;t measure network throughput. A nonzero client bandwidth limit controls outgoing fragments: each waits until enough byte credit is available, and the credit bucket can hold one full DH fragment message. A bandwidth limit of zero means unlimited. When the client changes its configuration, generation and sync settings are acknowledged independently. See the plugin README for current queue and transfer settings; their defaults remain provisional until real-runtime measurements are complete.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};